(function () {
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => Array.from(r.querySelectorAll(s));

  let mode = "flights";
  let tripType = "oneway";
  let heroChatBooted = false;
  let heroChatBusy = false;

  function isoPlus(days) {
    const d = new Date();
    d.setDate(d.getDate() + days);
    return d.toISOString().slice(0, 10);
  }

  function setMode(next) {
    mode = next;
    const dock = $("#search");
    const panel = $("#vero-panel");
    const form = $("#search-form");
    $$(".dock__mode").forEach((b) => {
      const on = b.dataset.mode === next;
      b.classList.toggle("is-on", on);
      b.setAttribute("aria-selected", on ? "true" : "false");
    });
    $("#fields-flights").hidden = next !== "flights";
    $("#fields-hotels").hidden = next !== "hotels";
    $("#fields-experiences").hidden = next !== "experiences";
    const tripBar = $("#trip-type");
    if (tripBar) tripBar.hidden = next !== "flights";
    const labels = {
      flights: "Search flights",
      hotels: "Search hotels",
      experiences: "Search experiences",
      vero: "Ask Vero",
    };
    const go = $("#search-go");
    if (go) go.textContent = labels[next] || "Search";

    const isChat = next === "vero";
    dock?.classList.toggle("is-chat", isChat);
    if (form) form.hidden = isChat;
    if (panel) panel.hidden = !isChat;
    const pop = $("#dock-pop");
    if (pop) {
      pop.hidden = true;
      pop.innerHTML = "";
    }
    if (next === "flights") setTripType(tripType, true);
    else {
      dock?.classList.remove("is-multi");
      const multi = $("#fields-multi");
      if (multi) multi.hidden = true;
    }
    if (isChat) {
      bootHeroChat();
      setTimeout(() => $("#vero-input")?.focus(), 80);
    }
  }

  function setTripType(next, silent) {
    tripType = next || "oneway";
    const val = $("#trip-type-val");
    if (val) val.value = tripType;
    $$(".dock__trip-btn").forEach((b) => {
      const on = b.dataset.trip === tripType;
      b.classList.toggle("is-on", on);
      b.setAttribute("aria-checked", on ? "true" : "false");
    });
    const fields = $("#fields-flights");
    const ret = $("#return-cell");
    const multi = $("#fields-multi");
    const dock = $("#search");
    if (fields) fields.dataset.trip = tripType;
    if (ret) ret.hidden = tripType !== "round";
    if (multi) multi.hidden = tripType !== "multi";
    dock?.classList.toggle("is-multi", tripType === "multi" && mode === "flights");
    if (!silent && tripType === "round") {
      const depart = $("#depart-date")?.value;
      const retIn = $("#return-date");
      const retFace = $("#return-face");
      if (retIn && (!retIn.value || (depart && retIn.value < depart))) {
        const base = depart || isoPlus(14);
        const d = parseIso(base) || new Date();
        d.setDate(d.getDate() + 7);
        retIn.value = toIso(d);
        if (retFace) retFace.textContent = formatFaceDate(retIn.value);
      }
    }
    if (!silent && tripType === "multi") {
      const d2 = $("#depart2-date");
      const f2 = $("#depart2-face");
      const depart = $("#depart-date")?.value || isoPlus(14);
      if (d2 && !d2.value) {
        const d = parseIso(depart) || new Date();
        d.setDate(d.getDate() + 3);
        d2.value = toIso(d);
        if (f2) f2.textContent = formatFaceDate(d2.value);
      }
      // keep leg 2 from = leg 1 to
      const dest = $("#dest-input")?.value;
      const o2 = $("#origin2-input");
      if (dest && o2 && (!o2.value || o2.dataset.auto !== "0")) {
        o2.value = dest;
        o2.dataset.auto = "1";
      }
    }
  }

  function escapeHtml(s) {
    return String(s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function scrollThread() {
    const thread = $("#vero-thread");
    if (thread) thread.scrollTop = thread.scrollHeight;
  }

  function hideIntro() {
    $("#vero-intro")?.classList.add("is-gone");
  }

  function appendMsg(role, text, actionsHtml) {
    const thread = $("#vero-thread");
    if (!thread) return null;
    hideIntro();
    const wrap = document.createElement("div");
    wrap.className = `vc-msg vc-msg--${role}`;
    const actions = actionsHtml
      ? `<div class="vc-msg__actions">${actionsHtml}</div>`
      : "";
    if (role === "vero") {
      wrap.innerHTML = `<img class="vc-msg__face" src="/vero-chatbot.png" alt="" width="26" height="26" /><div class="vc-msg__col"><div class="vc-msg__bubble">${escapeHtml(
        text
      )}</div>${actions}</div>`;
    } else {
      wrap.innerHTML = `<div class="vc-msg__col"><div class="vc-msg__bubble">${escapeHtml(
        text
      )}</div></div>`;
    }
    thread.appendChild(wrap);
    scrollThread();
    return wrap;
  }

  function showTyping() {
    const thread = $("#vero-thread");
    if (!thread) return null;
    hideIntro();
    const wrap = document.createElement("div");
    wrap.className = "vc-msg vc-msg--vero vc-msg--typing";
    wrap.id = "vero-typing";
    wrap.innerHTML =
      '<img class="vc-msg__face" src="/vero-chatbot.png" alt="" width="26" height="26" /><div class="vc-msg__col"><div class="vc-msg__bubble"><i></i><i></i><i></i></div></div>';
    thread.appendChild(wrap);
    scrollThread();
    return wrap;
  }

  function hideTyping() {
    $("#vero-typing")?.remove();
  }

  function veroReply(userText) {
    const q = userText.toLowerCase();
    if (/kyoto|japan|temple/.test(q)) {
      return "Kyoto vibes: walkable stays, food-first days, and flights that won’t eat the whole budget.";
    }
    if (/lisbon|portugal/.test(q)) {
      return "Lisbon is great for hills and late dinners. I’ll aim for morning flights and stays near Alfama or Baixa.";
    }
    if (/beach|bali|goa|maldives/.test(q)) {
      return "Beach mode on. I’ll keep resorts chill and the total under your ceiling. Skip the tourist traps.";
    }
    if (/budget|₹|rs\.?|under/.test(q)) {
      return "Budget locked. I’ll prefer non-stops when the gap is small, and free-cancellation stays when I can.";
    }
    return "Got it. I’ll shape flights + stays around that, then you can jump into live planning.";
  }

  function syncSendBtn() {
    const input = $("#vero-input");
    const btn = $("#vero-send");
    if (!input || !btn) return;
    btn.disabled = !input.value.trim() || heroChatBusy;
  }

  function bootHeroChat() {
    if (heroChatBooted) return;
    heroChatBooted = true;
    /* intro markup already in HTML */
  }

  function sendHeroChat(text) {
    const msg = String(text || "").trim();
    if (!msg || heroChatBusy) return;
    heroChatBusy = true;
    syncSendBtn();
    const suggest = $("#vero-chips");
    if (suggest) {
      suggest.classList.add("is-gone");
      suggest.setAttribute("hidden", "");
    }
    appendMsg("you", msg);
    const input = $("#vero-input");
    if (input) input.value = "";
    syncSendBtn();
    showTyping();
    setTimeout(() => {
      hideTyping();
      const reply = veroReply(msg);
      const actions = `<a class="vc-act--primary" href="/?vero=${encodeURIComponent(
        msg
      )}">Continue with Vero</a><button type="button" class="vc-act--ghost" data-more="1">Keep chatting</button>`;
      const bubble = appendMsg("vero", reply, actions);
      const more = bubble?.querySelector("[data-more]");
      more?.addEventListener("click", () => {
        more.closest(".vc-msg__actions")?.remove();
        appendMsg("vero", "Sure. Add dates, travellers, or must-haves and I’ll refine.");
        $("#vero-input")?.focus();
      });
      heroChatBusy = false;
      syncSendBtn();
      $("#vero-input")?.focus();
    }, 850 + Math.min(600, msg.length * 10));
  }

  function wireHeroChat() {
    $("#vero-form")?.addEventListener("submit", (e) => {
      e.preventDefault();
      sendHeroChat($("#vero-input")?.value);
    });
    $("#vero-input")?.addEventListener("input", syncSendBtn);
    $$("#vero-chips [data-chip]").forEach((btn) => {
      btn.addEventListener("click", () => sendHeroChat(btn.dataset.chip));
    });
    syncSendBtn();
  }

  function setHero(url) {
    const img = $("#stage-img");
    if (!img || !url) return;
    const probe = new Image();
    probe.onload = () => {
      img.style.transition = "opacity 0.45s ease";
      img.style.opacity = "0";
      setTimeout(() => {
        img.src = url;
        img.style.opacity = "1";
      }, 220);
    };
    probe.src = url;
  }

  const RECENT_KEY = "itinero_proto_recent_v3";

  const ICON_FLIGHT =
    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M21 16v-2l-8-5V3.5a1.5 1.5 0 00-3 0V9l-8 5v2l8-2.5V19l-2 1.5V22l3.5-1 3.5 1v-1.5L13 19v-5.5l8 2.5z" stroke-linejoin="round"/></svg>';
  const ICON_HOTEL =
    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M4 20V8.5A2.5 2.5 0 016.5 6H14a2 2 0 012 2v12M4 20h16M8 10h.01M8 13h.01M11 10h.01M11 13h.01M16 20v-5a1 1 0 011-1h2a1 1 0 011 1v5" stroke-linecap="round"/></svg>';
  const ICON_GO =
    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" aria-hidden="true"><path d="M9.5 6L15 12l-5.5 6" stroke-linecap="round" stroke-linejoin="round"/></svg>';

  /* Populated from /homepage/brand-media.json via ItineroBrandMedia */
  let FLIGHT_ROUTES = [];
  let FORK_BY_CITY = {};
  let FORK_FALLBACK = null;
  let WORLD_STAYS = [];
  let NEAR_BY_CITY = {};
  let HOME_LOCALE = {};

  function hydrateBrandCatalog() {
    const bm = window.ItineroBrandMedia;
    if (!bm || !bm.ready()) return false;
    if (typeof bm.resetPhotoClaims === "function") bm.resetPhotoClaims();
    if (typeof bm.claimHeroPlaylist === "function") bm.claimHeroPlaylist();
    const routesFn = typeof bm.flightRoutes === "function" ? bm.flightRoutes : bm.flightDeals;
    FLIGHT_ROUTES = (routesFn && routesFn.call(bm, HOME_LOCALE)) || [];
    FORK_BY_CITY = bm.forkByCity() || {};
    FORK_FALLBACK = bm.forkFallback(HOME_LOCALE.country) || null;
    WORLD_STAYS = bm.worldStays() || [];
    NEAR_BY_CITY = bm.nearByCity() || {};
    return true;
  }

  function titleCasePlace(raw) {
    const s = String(raw || "").trim().replace(/\s+/g, " ");
    if (!s) return "";
    if (/^[A-Z]{3}\s*[→\-–—]\s*[A-Z]{3}$/i.test(s)) {
      return s.toUpperCase().replace(/\s*[→\-–—]\s*/, " → ");
    }
    const small = new Set(["of", "the", "and", "de", "da", "del", "la", "le"]);
    return s
      .toLowerCase()
      .split(" ")
      .map((w, i) => {
        if (/^[A-Z]{3}$/i.test(w) && w.length === 3) return w.toUpperCase();
        if (i > 0 && small.has(w)) return w;
        return w.charAt(0).toUpperCase() + w.slice(1);
      })
      .join(" ");
  }

  function resolveRecentMedia(r) {
    const existing = r.thumb || r.img || r.bg || "";
    if (existing) return { thumb: existing, bg: r.bg || existing };
    const bm = window.ItineroBrandMedia;
    if (!bm || typeof bm.mediaFor !== "function") return { thumb: "", bg: "" };
    const hint = String(r.destination || r.hotel || r.city || r.label || r.to || "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "");
    const aliases = {
      lisbon: "lisbon",
      alibaug: "alibaug",
      lonavala: "lonavala",
      mumbai: "mumbai",
      goa: "goa",
      goi: "goa",
      paris: "paris",
      cdg: "paris",
      tokyo: "tokyo",
      nrt: "tokyo",
      dubai: "dubai",
      dxb: "dubai",
      bali: "bali",
      dps: "bali",
      "state-college": "new-york",
      "new-york": "new-york",
      delhi: "delhi",
      "new-delhi": "delhi",
    };
    const id = aliases[hint] || hint;
    const m = bm.mediaFor(id, { role: "stay", cardW: 480, heroW: 1200, salt: "recent:" + id });
    return { thumb: m.img || "", bg: m.bg || m.img || "" };
  }

  function guessHomeCity() {
    const city = String(HOME_LOCALE.city || "").trim();
    if (city) return city;
    const cc = String(HOME_LOCALE.country || "").toUpperCase();
    if (cc === "US") return "New York";
    if (cc === "IN") return "Mumbai";
    if (cc === "GB") return "London";
    if (cc === "AE") return "Dubai";
    if (cc === "SG") return "Singapore";
    if (cc === "AU") return "Sydney";
    try {
      const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || "";
      if (/Kolkata|Calcutta/i.test(tz)) return "Mumbai";
      if (/Dubai/i.test(tz)) return "Dubai";
      if (/New_York|Chicago|Denver|Los_Angeles|Phoenix|Detroit/i.test(tz)) return "New York";
      if (/London/i.test(tz)) return "London";
    } catch (_) {}
    // Never invent Mumbai for unknown geo — near rail uses live coords / empty honest state.
    return "";
  }

  function forkHomeKey() {
    const city = guessHomeCity();
    if (/state\s*college/i.test(city)) return "State College";
    if (/philadelphia|philly/i.test(city)) return "Philadelphia";
    if (/new\s*york|brooklyn|manhattan|queens/i.test(city)) return "New York";
    if (/mumbai|bombay/i.test(city)) return "Mumbai";
    if (/delhi|noida|gurugram|gurgaon/i.test(city)) return "Delhi";
    if (/bangalore|bengaluru/i.test(city)) return "Bangalore";
    const cc = String(HOME_LOCALE.country || "").toUpperCase();
    if (cc === "IN") return "Mumbai";
    if (cc === "US") return city || "New York";
    return city;
  }

  function readRecent() {
    try {
      const raw = localStorage.getItem(RECENT_KEY);
      const list = raw ? JSON.parse(raw) : [];
      return Array.isArray(list) ? list.slice(0, 4) : [];
    } catch (_) {
      return [];
    }
  }

  function writeRecent(list) {
    try {
      localStorage.setItem(RECENT_KEY, JSON.stringify(list.slice(0, 4)));
    } catch (_) {}
  }

  function mediaThumb(id, w) {
    const bm = window.ItineroBrandMedia;
    if (!bm || typeof bm.mediaFor !== "function") return { img: "", bg: "" };
    return bm.mediaFor(id, { cardW: w || 400, heroW: 1600 });
  }

  /** Drop the old seeded “demo recent” pack so empty state stays honest. */
  function scrubSeededRecent() {
    const DEMO = new Set(["h:Lisbon", "h:Alibaug", "f:BLR-GOI:oneway", "h:Lonavala"]);
    const items = readRecent();
    if (!items.length) return;
    if (items.every((r) => DEMO.has(r.key))) {
      try {
        localStorage.removeItem(RECENT_KEY);
      } catch (_) {}
    }
  }

  function pushRecent(entry) {
    const next = { ...entry };
    next.label = titleCasePlace(next.label || next.hotel || next.city || "");
    if (next.hotel) next.hotel = titleCasePlace(next.hotel);
    if (next.city && next.kind === "hotel") next.city = titleCasePlace(next.city);
    const media = resolveRecentMedia(next);
    if (!next.thumb && media.thumb) next.thumb = media.thumb;
    if (!next.bg && media.bg) next.bg = media.bg;
    writeRecent([next, ...readRecent().filter((r) => r.key !== next.key)].slice(0, 4));
    renderRecent();
  }

  function applyFlight(d, opts = {}) {
    setHero(d.bg);
    setMode("flights");
    const o = document.querySelector('#fields-flights input[name="origin"]');
    const dest = document.querySelector('#fields-flights input[name="destination"]');
    if (o) o.value = d.from;
    if (dest) dest.value = d.to;
    if (!opts.skipRecent) {
      pushRecent({
        key: `f:${d.from}-${d.to}:oneway`,
        kind: "flight",
        label: `${d.from} → ${d.to}`,
        sub: d.city,
        meta: `Flights · ${d.city}`,
        trip: "oneway",
        tripLabel: "One way",
        from: d.from,
        to: d.to,
        city: d.city,
        bg: d.bg,
      });
    }
    $("#search")?.scrollIntoView({ behavior: "smooth", block: "center" });
  }

  function hotelsProtoUrl(opts = {}) {
    const q = new URLSearchParams();
    if (opts.destination) q.set("destination", opts.destination);
    if (opts.checkin) q.set("checkin", opts.checkin);
    if (opts.checkout) q.set("checkout", opts.checkout);
    if (opts.guests) q.set("guests", String(opts.guests));
    q.set("rooms", String(opts.rooms || 1));
    const qs = q.toString();
    return `/hotels${qs ? `?${qs}` : ""}`;
  }

  function applyHotel(h, opts = {}) {
    setHero(h.bg);
    setMode("hotels");
    const input = document.querySelector('#fields-hotels input[name="hotel_dest"]');
    if (input) input.value = h.city;
    if (!opts.skipRecent) {
      pushRecent({
        key: `h:${h.city}`,
        kind: "hotel",
        label: h.city,
        sub: h.area || "Hotels",
        meta: h.area ? `Hotels · ${h.area}` : "Hotels",
        hotel: h.city,
        bg: h.bg,
        thumb: h.img || h.thumb,
      });
    }
    if (opts.navigate !== false && !opts.skipRecent) {
      location.href = hotelsProtoUrl({
        destination: h.city,
        checkin: opts.checkin || isoPlus(21),
        checkout: opts.checkout || isoPlus(23),
        guests: opts.guests || "2",
      });
      return;
    }
    $("#search")?.scrollIntoView({ behavior: "smooth", block: "center" });
  }

  function flightsResultsUrl(d) {
    const q = new URLSearchParams({
      from: d.from || "BOM",
      to: d.to || "DXB",
      depart: isoPlus(21),
      adults: "1",
      trip: "oneway",
      cabin: "ECONOMY",
    });
    return `/flights/results/?${q.toString()}`;
  }

  function routeCardHtml(d, i, featured) {
    const href = escapeHtml(flightsResultsUrl(d));
    const pair = `${escapeHtml(d.from || "")} → ${escapeHtml(d.to || "")}`;
    const city = escapeHtml(d.city || "");
    const blurb = escapeHtml(d.blurb || "");
    const bm = window.ItineroBrandMedia;
    const rawImg =
      d.img ||
      (bm && typeof bm.unsplashFallback === "function"
        ? bm.unsplashFallback(d.destination || "", { w: 1100, q: 75 })
        : "https://images.unsplash.com/photo-1488646953014-85cb44e25828?auto=format&fit=crop&w=1100&q=75");
    const img = escapeHtml(rawImg);
    const load = i === 0 ? "eager" : "lazy";
    if (featured) {
      return `
      <a class="route-lead" href="${href}" data-route="${i}">
        <span class="route-lead__media" aria-hidden="true">
          <img src="${img}" alt="" width="1400" height="900" loading="${load}" decoding="async" />
        </span>
        <span class="route-lead__veil" aria-hidden="true"></span>
        <span class="route-lead__copy">
          <span class="route-lead__pair">${pair}</span>
          <strong class="route-lead__city">${city}</strong>
          <span class="route-lead__blurb">${blurb}</span>
          <span class="route-lead__go">Open live fares</span>
        </span>
      </a>`;
    }
    return `
      <a class="route-lane" href="${href}" data-route="${i}">
        <span class="route-lane__media" aria-hidden="true">
          <img src="${img}" alt="" width="640" height="480" loading="${load}" decoding="async" />
        </span>
        <span class="route-lane__body">
          <span class="route-lane__pair">${pair}</span>
          <strong class="route-lane__city">${city}</strong>
          <span class="route-lane__blurb">${blurb}</span>
        </span>
        <span class="route-lane__go" aria-hidden="true">
          <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M5 12h12M13 6l6 6-6 6" stroke-linecap="round" stroke-linejoin="round"/></svg>
        </span>
      </a>`;
  }

  function stayHtml(h, i, prefix) {
    const live = h.live ? ' data-live="1"' : "";
    const badge =
      h.score || h.label
        ? `<span class="hcard__badge">${h.score ? `<b>${escapeHtml(h.score)}</b> ` : ""}${escapeHtml(
            h.label || ""
          )}</span>`
        : "";
    const price =
      h.price
        ? `<span class="hcard__foot">
            <span class="hcard__price">
              <small>From</small>
              <strong>${escapeHtml(h.price)}</strong>
              <span class="hcard__night">/ night</span>
            </span>
          </span>`
        : `<span class="hcard__foot"><span class="hcard__cta-soft">See live stays</span></span>`;
    const bm = window.ItineroBrandMedia;
    const thumb =
      h.img ||
      (bm && typeof bm.unsplashFallback === "function"
        ? bm.unsplashFallback(h.destination || h.search || "", { w: 700, q: 75 })
        : "https://images.unsplash.com/photo-1488646953014-85cb44e25828?auto=format&fit=crop&w=700&q=75");
    return `
      <button type="button" class="hcard" data-stay="${prefix}${i}"${live}>
        <span class="hcard__media">
          <img src="${escapeHtml(thumb)}" alt="" width="400" height="240" loading="lazy" />
          ${badge}
        </span>
        <span class="hcard__body">
          <strong>${escapeHtml(h.title || "")}</strong>
          <span class="hcard__where">${escapeHtml(h.where || "")}</span>
          ${price}
        </span>
      </button>`;
  }

  function formatShortDay(iso) {
    const d = parseIso(iso);
    if (!d) return "";
    return `${String(d.getDate()).padStart(2, "0")} ${d.toLocaleDateString("en-GB", { month: "short" })}`;
  }

  function formatStayRange(checkin, checkout) {
    const a = parseIso(checkin);
    const b = parseIso(checkout);
    if (!a || !b) return "";
    const sameMonth = a.getMonth() === b.getMonth() && a.getFullYear() === b.getFullYear();
    const mon = b.toLocaleDateString("en-GB", { month: "short" });
    if (sameMonth) {
      return `${String(a.getDate()).padStart(2, "0")} to ${String(b.getDate()).padStart(2, "0")} ${mon}`;
    }
    return `${formatShortDay(checkin)} to ${formatShortDay(checkout)}`;
  }

  function recentKindLabel(r) {
    return r.kind === "hotel" ? "Stays" : "Flights";
  }

  function recentMeta(r) {
    if (r.kind === "hotel") {
      const range = formatStayRange(r.checkin, r.checkout);
      const place = r.place || (r.sub && r.sub !== "Hotels" ? r.sub : "");
      if (range) return range;
      if (place) return place;
      if (r.meta) return r.meta;
      return r.guests ? `${r.guests} guests` : "Open search";
    }
    const trip = r.tripLabel || "One way";
    if (r.depart && r.returnDate && r.trip === "round") {
      return `${formatStayRange(r.depart, r.returnDate)} · ${trip}`;
    }
    if (r.depart) return `${formatShortDay(r.depart)} · ${trip}`;
    if (r.meta) return r.meta;
    return trip;
  }

