  function syncRecentNav() {
    const row = $("#recent-row");
    const prev = $("#recent-prev");
    const next = $("#recent-next");
    if (!row || !prev || !next) return;
    const max = row.scrollWidth - row.clientWidth;
    const canScroll = max > 8;
    prev.hidden = !canScroll || row.scrollLeft <= 4;
    next.hidden = !canScroll || row.scrollLeft >= max - 4;
  }

  function renderRecent() {
    const section = $("#recent");
    const row = $("#recent-row");
    if (!section || !row) return;
    let items = readRecent();
    if (!items.length) {
      section.hidden = true;
      return;
    }
    /* Normalize legacy messy entries once for display + storage */
    let dirty = false;
    items = items.map((r) => {
      const label = titleCasePlace(r.label || r.hotel || r.city || "");
      const media = resolveRecentMedia(r);
      const next = {
        ...r,
        label,
        thumb: r.thumb || r.img || media.thumb,
        bg: r.bg || media.bg,
      };
      if (next.label !== r.label || next.thumb !== r.thumb) dirty = true;
      return next;
    });
    if (dirty) writeRecent(items);
    section.hidden = false;
    row.innerHTML = items
      .map((r, i) => {
        const kind = r.kind === "hotel" ? "hotel" : "flight";
        const icon = kind === "hotel" ? ICON_HOTEL : ICON_FLIGHT;
        const thumb = recentThumb(r);
        const media = thumb
          ? `<img src="${escapeHtml(thumb)}" alt="" width="160" height="120" loading="lazy" decoding="async" />`
          : `<span class="recent__media-fallback" aria-hidden="true">${icon}</span>`;
        return `
      <button type="button" class="recent__card" data-recent="${i}" data-kind="${kind}" role="listitem">
        <span class="recent__media">${media}</span>
        <span class="recent__body">
          <span class="recent__kind">${recentKindLabel(r)}</span>
          <strong>${escapeHtml(r.label)}</strong>
          <span class="recent__meta">${escapeHtml(recentMeta(r))}</span>
        </span>
      </button>`;
      })
      .join("");
    requestAnimationFrame(syncRecentNav);
  }

  function wireRecent() {
    const row = $("#recent-row");
    row?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-recent]");
      if (!btn) return;
      const items = readRecent();
      restoreRecent(items[+btn.dataset.recent]);
    });
    row?.addEventListener("scroll", () => syncRecentNav(), { passive: true });
    window.addEventListener("resize", () => syncRecentNav());
    $("#recent-prev")?.addEventListener("click", () => {
      row?.scrollBy({ left: -280, behavior: "smooth" });
    });
    $("#recent-next")?.addEventListener("click", () => {
