    }

    function renderGuests(faceBtn) {
      const xp = faceBtn?.dataset.guests === "xp";
      const valEl = xp ? "#xp-guests-val" : "#guests-val";
      let n = Number($(valEl)?.value || 2);
      openPop("guests", faceBtn);

      function paint() {
        pop.innerHTML = `
          <div class="dock-pop__head"><p class="dock-pop__title">Guests</p></div>
          <div class="dock-pop__pax">
            <div class="dock-pop__row">
