    if (cin && !cin.value) cin.value = isoPlus(21);
    if (cout && !cout.value) cout.value = isoPlus(24);
    if (xstart && !xstart.value) xstart.value = isoPlus(21);
    if (xend && !xend.value) xend.value = isoPlus(24);
    const faces = [
      ["depart-face", depart],
      ["return-face", ret],
      ["depart2-face", dep2],
