  const PROTO_SESSION = "itinero_proto_session_v1";
  const TOKEN_KEY = "itinero_auth_token";

  function readSession() {
    const chrome = window.ItineroChrome;
    if (chrome?.readSession) return chrome.readSession();
    try {
      const raw = localStorage.getItem(PROTO_SESSION);
      const s = raw ? JSON.parse(raw) : null;
      if (!s || typeof s !== "object") return null;
      if (s.email || s.phone || s.id) return s;
      return null;
    } catch (_) {
      return null;
    }
  }

  function initialsFromSession(s) {
    if (s?.name) return s.name.trim().charAt(0).toUpperCase();
    const hint = String(s?.email || s?.phone || "A");
    return (hint.charAt(0) || "A").toUpperCase();
  }

  function localWatches() {
    try {
      const raw = JSON.parse(localStorage.getItem("itinero.wl.watches.v1") || "[]");
      return Array.isArray(raw) ? raw : [];
    } catch (_) {
      return [];
    }
  }

  function watchTitle(w) {
    if (!w || typeof w !== "object") return "Price watch";
    if (w.route) return String(w.route);
    if (w.name) return String(w.name);
    if (String(w.kind || "").toLowerCase() === "hotel") {
      return String(w.destination || w.destinationLabel || "Stay watch");
    }
    const o = w.origin || w.originLabel || "";
    const d = w.destination || w.destinationLabel || "";
    if (o && d) return `${o} → ${d}`;
    return "Price watch";
  }

  function watchHint(w) {
    if (!w || typeof w !== "object") return "";
    if (w.note) return String(w.note);
    if (w.lastAlertedAt) return "We emailed you when the live fare dropped.";
    const price = Number(w.lastPrice || w.baselinePrice || w.price || 0);
    const cur = String(w.currency || "").toUpperCase();
    if (price > 0) {
      try {
        return `Watching around ${new Intl.NumberFormat("en-US", {
          style: "currency",
          currency: cur || "USD",
          maximumFractionDigits: 0,
        }).format(price)} · not a price lock`;
      } catch (_) {
        return `Watching around ${cur} ${Math.round(price)} · not a price lock`;
      }
    }
    return "We email you if the live fare drops — not a price lock.";
  }

  function watchHref(w) {
    if (w?.href) return String(w.href);
    const o = encodeURIComponent(w?.origin || "");
    const d = encodeURIComponent(w?.destination || "");
    if (o && d) return `/flights/?from=${o}&to=${d}`;
    return "/flights/";
  }

  function mergeWatches(serverRows, localRows) {
    const out = [];
    const seen = new Set();
    const push = (w) => {
      if (!w || typeof w !== "object") return;
      const key =
        String(w.id || "") ||
        `${w.kind || "flight"}:${w.origin || ""}-${w.destination || ""}-${w.route || w.name || ""}`;
      if (!key || seen.has(key)) return;
      seen.add(key);
      out.push(w);
    };
    (serverRows || []).forEach(push);
    (localRows || []).forEach(push);
    return out;
  }

  function paintAlertsAuth(session) {
    const copy = $("#alerts-empty-copy") || $("#alerts-empty")?.querySelector(".sheet__empty-copy");
    const cta = $("#alerts-cta") || $("#alerts-panel")?.querySelector(".sheet__link");
    if (session) {
      if (copy) {
        copy.textContent =
          "Price watches and trip drafts show up here when you save them. We never invent placeholders.";
      }
      if (cta) {
        cta.hidden = false;
        cta.textContent = "Manage account";
        cta.setAttribute("href", "/account/");
      }
    } else {
      if (copy) {
        copy.textContent =
          "After you sign in, price watches and trip drafts show up here. We never use invented placeholders.";
      }
      if (cta) {
        cta.hidden = false;
        cta.textContent = "Sign in for live alerts";
        cta.setAttribute("href", "/homepage/signin.html");
      }
    }
  }

  async function refreshAlertsPanel(session) {
    paintAlertsAuth(session);
    const empty = $("#alerts-empty");
    const list = $("#alerts-list");
    const cta = $("#alerts-cta") || $("#alerts-panel")?.querySelector(".sheet__link");
    let server = [];
    if (session) {
      try {
        const chrome = window.ItineroChrome;
        const res = await fetch("/api/watches", {
          ...(chrome?.authFetchOpts?.() || { credentials: "include" }),
          headers: chrome?.authHeaders?.() || { Accept: "application/json" },
        });
        const data = await res.json().catch(() => ({}));
        if (res.ok && Array.isArray(data.watches)) server = data.watches;
      } catch (_) {
        /* keep local watches */
      }
    }
    const watches = mergeWatches(server, localWatches()).slice(0, 8);
    if (!watches.length) {
      if (empty) empty.hidden = false;
      if (list) {
        list.hidden = true;
        list.innerHTML = "";
      }
      paintAlertsAuth(session);
      return;
    }
    if (empty) empty.hidden = true;
    if (list) {
      list.hidden = false;
      list.innerHTML = watches
        .map((w) => {
          const href = escapeHtml(watchHref(w));
          const title = escapeHtml(watchTitle(w));
          const hint = escapeHtml(watchHint(w));
          return `<li><a href="${href}"><strong>${title}</strong><span>${hint}</span></a></li>`;
        })
        .join("");
    }
    if (cta) {
      if (session) {
        cta.hidden = false;
        cta.textContent = "Manage account";
        cta.setAttribute("href", "/account/");
      } else {
        cta.hidden = false;
        cta.textContent = "Sign in for live alerts";
        cta.setAttribute("href", "/homepage/signin.html");
      }
    }
  }

  function paintAuthChrome(session) {
    const signin = $("#top-signin");
    const account = $("#top-account");
    const drawerSignin = $("#drawer-signin");
    const drawerSignup = $("#drawer-signup");
    const drawerSignout = $("#drawer-signout");
    const drawerNote = $("#drawer-auth-note");
    const contact = session?.email || session?.phone || "";

    if (session) {
      if (signin) signin.hidden = true;
      if (account) account.hidden = false;
      const avatar = $("#account-avatar");
      const label = $("#account-label");
      const email = $("#account-email");
      if (avatar) avatar.textContent = initialsFromSession(session);
      if (label) label.textContent = session.name || "Account";
      if (email) email.textContent = contact;
      if (drawerSignin) drawerSignin.hidden = true;
      if (drawerSignup) drawerSignup.hidden = true;
      if (drawerSignout) drawerSignout.hidden = false;
      if (drawerNote) drawerNote.textContent = contact ? `Signed in as ${contact}` : "Signed in";
    } else {
      if (signin) signin.hidden = false;
      if (account) account.hidden = true;
      if (drawerSignin) {
        drawerSignin.hidden = false;
        drawerSignin.textContent = "Sign in";
        drawerSignin.href = "/homepage/signin.html";
      }
      if (drawerSignup) drawerSignup.hidden = false;
      if (drawerSignout) drawerSignout.hidden = true;
      if (drawerNote) drawerNote.textContent = "Sync trips, DNA, and alerts across devices.";
    }
    paintAlertsAuth(session);
  }

  function wireAuthChrome() {
    const chrome = window.ItineroChrome;
    // Shared chrome owns menu/sign-out when present — avoid double listeners.
    if (chrome?.wireChrome) {
      const sync = (session) => {
        chrome.wireChrome();
        paintAuthChrome(session || chrome.readSession?.() || readSession());
      };
