  function wireReveals() {
    const nodes = $$(".fx, .fx-scale");
    if (!("IntersectionObserver" in window)) {
      nodes.forEach((n) => n.classList.add("is-in"));
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;
          entry.target.classList.add("is-in");
          io.unobserve(entry.target);
        });
      },
      { threshold: 0.18, rootMargin: "0px 0px -8% 0px" }
    );
    nodes.forEach((n) => io.observe(n));
  }

  function wireSearch() {
    $("#search-form")?.addEventListener("submit", (e) => {
      e.preventDefault();
      if (mode === "vero") return;
      const fd = new FormData(e.target);
      if (mode === "flights") {
        const origin = String(fd.get("origin") || "BOM").toUpperCase().slice(0, 3);
        const destination = String(fd.get("destination") || "DEL").toUpperCase().slice(0, 3);
        const depart = fd.get("depart") || isoPlus(14);
        const ret = fd.get("return") || "";
        const trip = fd.get("trip_type") || tripType || "oneway";
        const adults = fd.get("adults") || "1";
        const cabin = fd.get("cabin") || "Economy";
        const tripLabel = trip === "round" ? "Round trip" : trip === "multi" ? "Multi-city" : "One way";
        pushRecent({
          key: `f:${origin}-${destination}:${trip}`,
          kind: "flight",
          label: `${origin} → ${destination}`,
          sub: destination,
          trip,
          tripLabel,
          depart,
          returnDate: ret || "",
          from: origin,
          to: destination,
          city: destination,
        });
        let url = `/flights/results/?from=${encodeURIComponent(origin)}&to=${encodeURIComponent(
          destination
        )}&depart=${encodeURIComponent(depart)}&trip=${encodeURIComponent(
          trip === "round" ? "round" : "oneway"
        )}&adults=${encodeURIComponent(adults)}&cabin=${encodeURIComponent(
          String(cabin).toUpperCase().replace(/\s+/g, "_")
        )}`;
        if (trip === "round" && ret) url += `&return=${encodeURIComponent(ret)}`;
        if (trip === "multi") {
          // The V2 results page has no multi-city mode yet; keep the production SPA for it.
          url = `/flights?origin=${encodeURIComponent(origin)}&destination=${encodeURIComponent(
            destination
          )}&depart_date=${encodeURIComponent(depart)}&trip_type=multi&adults=${encodeURIComponent(
            adults
          )}&cabin_class=${encodeURIComponent(cabin)}`;
          const o2 = String(fd.get("origin2") || destination).toUpperCase().slice(0, 3);
          const d2 = String(fd.get("destination2") || "BLR").toUpperCase().slice(0, 3);
          const dep2 = fd.get("depart2") || depart;
          url += `&origin2=${encodeURIComponent(o2)}&destination2=${encodeURIComponent(
            d2
          )}&depart_date2=${encodeURIComponent(dep2)}`;
        }
        location.href = url;
        return;
      }
      if (mode === "hotels") {
        const dest = fd.get("hotel_dest") || "New Delhi";
        const checkin = fd.get("checkin") || isoPlus(21);
        const checkout = fd.get("checkout") || isoPlus(22);
        const guests = fd.get("guests_n") || "2";
        pushRecent({
          key: `h:${dest}`,
          kind: "hotel",
          label: String(dest),
          sub: "Hotels",
          hotel: String(dest),
          checkin,
          checkout,
          guests,
        });
        location.href = hotelsProtoUrl({
          destination: dest,
          checkin,
          checkout,
          guests,
          rooms: 1,
        });
        return;
      }
      if (mode === "experiences") {
        const city = fd.get("xp_city") || "Tokyo";
        const start = fd.get("xp_start") || isoPlus(21);
        const end = fd.get("xp_end") || isoPlus(24);
        const guests = fd.get("xp_guests") || "2";
        const q = new URLSearchParams();
        q.set("city", String(city).trim());
        q.set("start", start);
        q.set("end", end);
        q.set("guests", guests);
        location.href = `/experiences/results/?${q.toString()}`;
      }
    });
  }

